module challenge24 (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] a,\n    input wire [7:0] b,\n    input wire [7:0] c,\n    input wire [7:0] d,\n    output reg [7:0] grade,\n    output reg done\n);\n\n    // State declarations\n    localparam [3:0] IDLE       = 4'd0;\n    localparam [3:0] INIT       = 4'd1;\n    localparam [3:0] EVAL_EXPR  = 4'd2;\n    localparam [3:0] ITERATE    = 4'd3;\n    localparam [3:0] FINISH     = 4'd4;\n    \n    reg [3:0] state, next_state;\n    \n    // Control registers\n    reg [7:0] min_grade;\n    reg [4:0] perm_idx;\n    reg [1:0] op1, op2, op3;\n    reg [2:0] tree_idx;\n    reg [7:0] n0, n1, n2, n3;\n    reg [15:0] temp_result;\n    reg temp_valid;\n    \n    // Evaluation wires\n    wire [15:0] eval_result;\n    wire eval_valid;\n    wire [7:0] current_grade;\n    wire is_24;\n    \n    // Function: compute_op\n    function [16:0] compute_op;\n        input [15:0] a, b;\n        input [1:0] op;\n        reg [15:0] res, remainder;\n        reg valid;\n        begin\n            valid = 1'b1;\n            case(op)\n                2'b00: res = a + b;\n                2'b01: res = a - b;\n                2'b10: res = a * b;\n                2'b11: begin\n                    if (b == 16'd0) begin\n                        valid = 1'b0;\n                        res = 16'd0;\n                    end else begin\n                        remainder = a % b;\n                        res = a / b;\n                        if (remainder != 16'd0) valid = 1'b0;\n                    end\n                end\n                default: begin\n                    valid = 1'b0;\n                    res = 16'd0;\n                end\n            endcase\n            compute_op = {valid, res};\n        end\n    endfunction\n\n    // Grade calculation function\n    function [7:0] calc_grade;\n        input [2:0] tree;\n        input [1:0] op1, op2, op3;\n        reg [7:0] parens, inversions;\n        begin\n            case(tree)\n                3'd0: parens = 8'd2;\n                3'd1: parens = 8'd3;\n                3'd2: parens = 8'd3;\n                3'd3: parens = 8'd2;\n                3'd4: parens = 8'd2;\n                default: parens = 8'd0;\n            endcase\n            inversions = ((op1 == 2'b01) || (op1 == 2'b11)) +\n                        ((op2 == 2'b01) || (op2 == 2'b11)) +\n                        ((op3 == 2'b01) || (op3 == 2'b11));\n            calc_grade = parens + (inversions << 1);\n        end\n    endfunction\n\n    // Expression evaluator\n    assign is_24 = eval_valid && (eval_result == 16'd24);\n    assign current_grade = calc_grade(tree_idx, op1, op2, op3);\n\n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            perm_idx <= 5'd0;\n            op1 <= 2'd0;\n            op2 <= 2'd0;\n            op3 <= 2'd0;\n            tree_idx <= 3'd0;\n            min_grade <= 8'hFF;\n            done <= 1'b0;\n            grade <= 8'hFF;\n        end else begin\n            case(state)\n                IDLE: begin\n                    if (start) begin\n                        state <= INIT;\n                        done <= 1'b0;\n                    end\n                end\n                \n                INIT: begin\n                    min_grade <= 8'hFF;\n                    perm_idx <= 5'd0;\n                    op1 <= 2'd0;\n                    op2 <= 2'd0;\n                    op3 <= 2'd0;\n                    tree_idx <= 3'd0;\n                    state <= EVAL_EXPR;\n                end\n                \n                EVAL_EXPR: begin\n                    state <= ITERATE;\n                    if (temp_valid) begin\n                        if (is_24 && (current_grade < min_grade))\n                            min_grade <= current_grade;\n                    end\n                end\n                \n                ITERATE: begin\n                    // Increment tree\n                    if (tree_idx < 3'd4) begin\n                        tree_idx <= tree_idx + 1;\n                        state <= EVAL_EXPR;\n                    end else begin\n                        tree_idx <= 3'd0;\n                        \n                        // Increment op3\n                        if (op3 < 2'd3) begin\n                            op3 <= op3 + 1;\n                            state <= EVAL_EXPR;\n                        end else begin\n                            op3 <= 2'd0;\n                            \n                            // Increment op2\n                            if (op2 < 2'd3) begin\n                                op2 <= op2 + 1;\n                                state <= EVAL_EXPR;\n                            end else begin\n                                op2 <= 2'd0;\n                                \n                                // Increment op1\n                                if (op1 < 2'd3) begin\n                                    op1 <= op1 + 1;\n                                    state <= EVAL_EXPR;\n                                end else begin\n                                    op1 <= 2'd0;\n                                    \n                                    // Increment perm\n                                    if (perm_idx < 5'd23) begin\n                                        perm_idx <= perm_idx + 1;\n                                        state <= EVAL_EXPR;\n                                    end else begin\n                                        state <= FINISH;\n                                    end\n                                end\n                            end\n                        end\n                    end\n                end\n                \n                FINISH: begin\n                    done <= 1'b1;\n                    grade <= min_grade;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n\n    // Permutations selector\n    always @(*) begin\n        case(perm_idx)\n            5'd0: {n0, n1, n2, n3} = {a, b, c, d};\n            5'd1: {n0,1: {n0, n1, n2, n3} = {a, b, d, c};\n            5'd2: {n0, n1, n2, n3} = {a, c, b, d};\n            5'd3: {n0, n1, n2, n3} = {a, c, d, b};\n            5'd4: {n0, n1, n2, n3} = {a, d, b, c};\n            5'd5: {n0, n1, n2, n3} = {a, d, c, b};\n            5'd6: {n0, n1, n2, n3} = {b, a, c, d};\n            5'd7: {n0, n1, n2, n3} = {b, a, d, c};\n            5'd8: {n0, n1, n2, n3} = {b, c, a, d};\n            5'd9: {n0, n1, n2, n3} = {b, c, d, a};\n            5'd10: {n0, n1, n2, n3} = {b, d, a, c};\n            5'd11: {n0, n1, n2, n3} = {b, d, c, a};\n            5'd12: {n0, n1, n2, n3} = {c, a, b, d};\n            5'd13: {n0, n1, n2, n3} = {c, a, d, b};\n            5'd14: {n0, n1, n2, n3} = {c, b, a, d};\n            5'd15: {n0, n1, n2, n3} = {c, b, d, a};\n            5'd16: {n0, n1, n2, n3} = {c, d, a, b};\n            5'd17: {n0, n1, n2, n3} = {c, d, b, a};\n            5'd18: {n0, n1, n2, n3} = {d, a, b, c};\n            5'd19: {n0, n1, n2, n3} = {d, a, c, b};\n            5'd20: {n0, n1, n2, n3} = {d, b, a, c};\n            5'd21: {n0, n1, n2, n3} = {d, b, c, a};\n            5'd22: {n0, n1, n2, n3} = {d, c, a, b};\n            5'd23: {n0, n1, n2, n3} = {d, c, b, a};\n            default: {n0, n1, n2, n3} = {a, b, c, d};\n        endcase\n    end\n\n    // Expression evaluator\n    always @(*) begin\n        temp_valid = 1'b0;\n        eval_result = 16'd0;\n        eval_valid = 1'b0;\n        case(tree_idx)\n            3'd0: begin  // ((n0 op1 n1) op2 n2) op3 n3\n                {temp_valid, eval_result} = compute_op(\n                    compute_op(\n                        compute_op(\n                            {8'd0, n0}, {8'd0, n1}, op1\n                        )[15:0],\n                        {8'd0, n2}, op2\n                    )[15:0],\n                    {8'd0, n3}, op3\n                );\n            end\n            3'd1: begin  // (n0 op1 (n1 op2 n2)) op3 n3\n                {temp_valid, eval_result} = compute_op(\n                    compute_op(\n                        {8'd0, n0},\n                        compute_op({8'd0, n1}, {8'd0, n2}, op2)[15:0],\n                        op1\n                    )[15:0],\n                    {8'd0, n3}, op3\n                );\n            end\n            3'd2: begin  // n0 op1 ((n1 op2 n2) op3 n3)\n                {temp_valid, eval_result} = compute_op(\n                    {8'd0, n0},\n                    compute_op(\n                        compute_op({8'd0, n1}, {8'd0, n2}, op2)[15:0],\n                        {8'd0, n3}, op3\n                    )[15:0],\n                    op1\n                );\n            end\n            3'd3: begin  // n0 op1 (n1 op2 (n2 op3 n3))\n                {temp_valid, eval_result} = compute_op(\n                    {8'd0, n0},\n                    compute_op(\n                        {8'd0, n1},\n                        compute_op({8'd0, n2}, {8'd0, n3}, op3)[15:0],\n                        op2\n                    )[15:0],\n                    op1\n                );\n            end\n            3'd4: begin  // (n0 op1 n1) op2 (n2 op3 n3)\n                {temp_valid, eval_result} = compute_op(\n                    compute_op({8'd0, n0}, {8'd0, n1}, op1)[15:0],\n                    compute_op({8'd0, n2}, {8'd0, n3}, op3)[15:0],\n                    op2\n                );\n            end\n        endcase\n        eval_valid = temp_valid;\n    end\n\nendmodule\n